// ── Question builder ──────────────────────────────────────────────────────────
function renderQuestionList() {
  const ql = $('questions-list');
  ql.innerHTML = questions.map((q, qi) => `
    <div class="q-card" data-qi="${qi}">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
        <div style="display:flex;align-items:center;gap:8px">
          <span class="q-drag-handle" title="Glisser pour réordonner"
                style="color:var(--muted);cursor:grab;font-size:1.3rem;padding:4px 6px;
                       border-radius:6px;touch-action:none;user-select:none"
                onmouseenter="this.style.color='var(--accent)'"
                onmouseleave="this.style.color='var(--muted)'">⠿</span>
          <strong style="font-family:var(--font-head);font-weight:900;font-size:1rem">Q${qi+1}</strong>
        </div>
        <div style="display:flex;gap:8px;align-items:center">
          <select class="input" style="width:auto;padding:6px 10px;font-size:.8rem" onchange="setTime(${qi},this.value)">
            ${[10,15,20,30,60].map(t=>`<option value="${t}" ${q.time===t?'selected':''}>${t}s</option>`).join('')}
          </select>
          <button class="btn btn-ghost btn-sm" style="color:var(--red);padding:6px 10px" onclick="removeQuestion(${qi})">✕</button>
        </div>
      </div>

      <input class="input" style="margin-bottom:10px;font-weight:700" placeholder="Question…"
             value="${escHtml(q.question)}" oninput="questions[${qi}].question=this.value">

      <p style="font-size:.72rem;color:var(--muted);margin-bottom:6px">✅ Cocher la/les bonne(s) réponse(s)</p>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:10px">
        ${q.answers.map((a,ai)=>{
          const correctArr = Array.isArray(q.correct) ? q.correct : [q.correct];
          const isChecked = correctArr.includes(ai);
          return `<div style="display:flex;gap:5px;align-items:center">
            <input type="checkbox" value="${ai}" ${isChecked?'checked':''}
                   onchange="toggleCorrect(${qi},${ai},this.checked)"
                   style="accent-color:var(--green);flex-shrink:0;width:16px;height:16px">
            <input class="input" style="padding:7px 9px;font-size:.82rem" placeholder="Réponse ${ai+1}"
                   value="${escHtml(a)}" oninput="questions[${qi}].answers[${ai}]=this.value">
          </div>`;
        }).join('')}
      </div>

      <!-- Explication -->
      <div style="margin-bottom:10px">
        <label style="display:block;font-size:.78rem;color:var(--muted);margin-bottom:5px;font-weight:600;letter-spacing:.3px">💡 EXPLICATION <span style="font-weight:400;opacity:.7">(affichée après la réponse)</span></label>
        <textarea class="input" rows="2"
               style="font-size:.95rem;resize:vertical;line-height:1.5;padding:10px 12px"
               placeholder="Entrez ici une explication ou un détail sur la bonne réponse…"
               oninput="questions[${qi}].explication=this.value" onclick="event.stopPropagation()">${escHtml(q.explication||'')}</textarea>
      </div>

      <!-- Image -->
      <div style="border-top:1px solid var(--border);padding-top:10px">
        <p style="font-size:.75rem;color:var(--muted);margin-bottom:8px">🖼 Illustration (optionnel)</p>
        <div style="display:flex;gap:8px;flex-wrap:wrap">
          <button class="btn btn-ghost btn-sm" onclick="pickImageFile(${qi})">📁 Ordi</button>
          <button class="btn btn-ghost btn-sm" onclick="pickImageUrl(${qi})">🔗 URL</button>
          ${q.image ? `<button class="btn btn-ghost btn-sm" style="color:var(--red)" onclick="removeImage(${qi})">✕</button>` : ''}
        </div>
        ${q.image ? `<img src="${q.image}" style="margin-top:8px;max-height:70px;max-width:100%;border-radius:8px;border:1px solid var(--border);object-fit:cover">` : ''}
        <input type="file" id="img-file-${qi}" accept="image/*" style="display:none" onchange="handleImageFile(${qi},event)">
      </div>
    </div>
  `).join('');
}

function toggleCorrect(qi, ai, checked) {
  let correctArr = Array.isArray(questions[qi].correct)
    ? [...questions[qi].correct]
    : [questions[qi].correct];
  if (checked) {
    if (!correctArr.includes(ai)) correctArr.push(ai);
  } else {
    correctArr = correctArr.filter(x => x !== ai);
    if (!correctArr.length) correctArr = [ai]; // au moins une réponse correcte
  }
  questions[qi].correct = correctArr.length === 1 ? correctArr[0] : correctArr;
}

// ── Mode réorganisation avec boutons explicites ──────────────────────────────
let dnd = null;

function enterReorderMode() {
  const list = $('questions-list');
  list.classList.add('reorder-mode');
  $('btn-reorder').style.display = 'none';
  $('btn-edit-mode').style.display = 'inline-flex';
  renderMiniCards();
}

function exitReorderMode() {
  const list = $('questions-list');
  list.classList.remove('reorder-mode');
  $('btn-reorder').style.display = 'inline-flex';
  $('btn-edit-mode').style.display = 'none';
  renderQuestionList();
}

function renderMiniCards() {
  const list = $('questions-list');
  list.innerHTML = questions.map((q, qi) => `
    <div class="q-card-mini" data-qi="${qi}">
      <span class="q-drag-handle">⠿</span>
      <span class="q-mini-num">Q${qi+1}</span>
      <span class="q-mini-text">${escHtml(q.question || '(sans titre)')}</span>
    </div>
  `).join('');
  // Délai avant déclenchement : 0ms souris, 600ms touch
  list.querySelectorAll('.q-card-mini').forEach(card => {
    card.addEventListener('contextmenu', e => e.preventDefault(), { passive: false });
    card.addEventListener('selectstart',  e => e.preventDefault(), { passive: false });

    // ── Souris : drag immédiat ──────────────────────────────────────────────
    card.addEventListener('mousedown', e => {
      if (e.button !== 0) return;
      e.preventDefault();
      startDrag({ clientX: e.clientX, clientY: e.clientY, isTouch: false }, card);
    });

    // ── Touch : hold 600ms, puis drag avec le touch en cours ────────────────
    let holdTimer = null;
    let touchStartX = 0, touchStartY = 0;
    let activeTouchId = null;

    card.addEventListener('touchstart', e => {
      e.stopPropagation();
      const t = e.changedTouches[0];
      touchStartX = t.clientX;
      touchStartY = t.clientY;
      activeTouchId = t.identifier;

      holdTimer = setTimeout(() => {
        holdTimer = null;
        if (navigator.vibrate) navigator.vibrate(40);
        // Bloquer le scroll AVANT de démarrer le drag
        card.style.touchAction = 'none';
        startDragTouch(card, activeTouchId);
      }, 600);
    }, { passive: true });

    card.addEventListener('touchmove', e => {
      if (!holdTimer) return; // drag déjà déclenché ou pas de timer
      const t = [...e.changedTouches].find(t => t.identifier === activeTouchId);
      if (!t) return;
      const dx = Math.abs(t.clientX - touchStartX);
      const dy = Math.abs(t.clientY - touchStartY);
      if (dx > 10 || dy > 10) { // mouvement = scroll, annuler
        clearTimeout(holdTimer); holdTimer = null;
      }
    }, { passive: true });

    card.addEventListener('touchend', () => {
      if (holdTimer) { clearTimeout(holdTimer); holdTimer = null; }
      card.style.touchAction = '';
    }, { passive: true });

    card.addEventListener('touchcancel', () => {
      if (holdTimer) { clearTimeout(holdTimer); holdTimer = null; }
      card.style.touchAction = '';
    }, { passive: true });
  });
}

// ── Drag déclenché par touch ────────────────────────────────────────────────
function startDragTouch(sourceCard, touchId) {
  const list = $('questions-list');
  const qi   = parseInt(sourceCard.dataset.qi);
  const rect = sourceCard.getBoundingClientRect();

  list.style.touchAction = 'none';
  list.style.overflowY   = 'hidden';

  // Trouver le touch actif pour les coordonnées initiales
  let initX = rect.left + rect.width / 2;
  let initY = rect.top  + rect.height / 2;

  const ghost = sourceCard.cloneNode(true);
  ghost.style.cssText = `position:fixed;z-index:9999;pointer-events:none;
    width:${rect.width}px;left:${rect.left}px;top:${rect.top}px;
    opacity:.88;transform:scale(1.04) rotate(1.5deg);
    box-shadow:0 16px 48px rgba(0,0,0,.65);
    border:2px solid var(--accent);border-radius:10px;transition:none;`;
  document.body.appendChild(ghost);

  sourceCard.style.opacity = '0';
  sourceCard.style.pointerEvents = 'none';

  const cards = [...list.querySelectorAll('.q-card-mini')];
  // ox/oy = offset du doigt par rapport au coin supérieur gauche du fantôme
  // On pose le fantôme centré sur la carte, donc offset = moitié largeur/hauteur
  const ox = rect.width  / 2;
  const oy = rect.height / 2;

  dnd = {
    qi, ghost, list, sourceCard,
    snapshots: [...list.querySelectorAll('.q-card-mini')].map(c => ({
      el: c, top: c.getBoundingClientRect().top, idx: parseInt(c.dataset.qi)
    })),
    ox, oy,
    currentInsert: qi,
    cardH: rect.height + 8,
    isTouch: true, touchId,
  };

  // Écouter les touch events sur le document
  document.addEventListener('touchmove',   onTouchDragMove,  { passive: false });
  document.addEventListener('touchend',    onTouchDragEnd,   { once: true, passive: true });
  document.addEventListener('touchcancel', onTouchDragEnd,   { once: true, passive: true });
}

function onTouchDragMove(e) {
  if (!dnd || !dnd.isTouch) return;
  e.preventDefault(); // bloquer le scroll
  const t = [...e.changedTouches].find(t => t.identifier === dnd.touchId)
         || e.changedTouches[0];
  if (!t) return;
  moveDrag(t.clientX, t.clientY);
}

function onTouchDragEnd(e) {
  if (!dnd || !dnd.isTouch) return;
  document.removeEventListener('touchmove', onTouchDragMove);
  finalizeDrag();
}

function startDrag(e, sourceCard) {
  const list  = $('questions-list');
  const qi    = parseInt(sourceCard.dataset.qi);
  const rect  = sourceCard.getBoundingClientRect();
  const cards = [...list.querySelectorAll('.q-card-mini')];

  // Snapshot des positions initiales de chaque carte (pour l'animation)
  const snapshots = cards.map(c => ({
    el:   c,
    top:  c.getBoundingClientRect().top,
    idx:  parseInt(c.dataset.qi),
  }));

  // Fantôme
  const ghost = sourceCard.cloneNode(true);
  ghost.style.cssText = `position:fixed;z-index:9999;pointer-events:none;
    width:${rect.width}px;left:${rect.left}px;top:${rect.top}px;
    opacity:.88;transform:scale(1.04) rotate(1.5deg);
    box-shadow:0 16px 48px rgba(0,0,0,.65);
    border:2px solid var(--accent);border-radius:10px;
    transition:none;`;
  document.body.appendChild(ghost);

  // La source devient invisible (garde son espace)
  sourceCard.style.opacity = '0';
  sourceCard.style.pointerEvents = 'none';

  dnd = {
    qi, ghost, list, sourceCard, snapshots,
    ox: e.clientX - rect.left,
    oy: e.clientY - rect.top,
    currentInsert: qi,
    cardH: rect.height + 8,
    isTouch: false,
  };

  document.addEventListener('mousemove', onMouseDragMove);
  document.addEventListener('mouseup',   onMouseDragEnd, { once: true });
}

function onMouseDragMove(e) {
  if (!dnd || dnd.isTouch) return;
  moveDrag(e.clientX, e.clientY);
}
function onMouseDragEnd() {
  if (!dnd || dnd.isTouch) return;
  document.removeEventListener('mousemove', onMouseDragMove);
  finalizeDrag();
}

function moveDrag(cx, cy) {
  if (!dnd) return;
  const { ghost, list, sourceCard, ox, oy, qi, cardH } = dnd;

  // Déplacer le fantôme
  ghost.style.left = (cx - ox) + 'px';
  ghost.style.top  = (cy - oy) + 'px';

  // Calculer la nouvelle position d'insertion (continue, pas binaire)
  const listRect = list.getBoundingClientRect();
  const relY     = e.clientY - listRect.top;
  const rawInsert = Math.round(relY / cardH);

  // Trouver plus précisément via les cartes visibles
  const visibleCards = [...list.querySelectorAll('.q-card-mini[data-qi]')]
    .filter(c => c !== sourceCard);
  let insertIdx = visibleCards.length; // par défaut: fin
  for (let i = 0; i < visibleCards.length; i++) {
    const r = visibleCards[i].getBoundingClientRect();
    // Zone d'activation : 30% depuis le haut de la carte (pas le milieu)
    if (e.clientY < r.top + r.height * 0.35) {
      insertIdx = i;
      break;
    }
  }
  // Convertir en index réel (sans la source)
  // insertIdx = position dans le tableau sans la source
  // Si on insère après qi, l'index réel est insertIdx
  // Si on insère avant qi, l'index réel est insertIdx
  const realInsert = insertIdx >= qi ? insertIdx : insertIdx;

  if (realInsert === dnd.currentInsert) return;
  dnd.currentInsert = realInsert;

  // Animer les cartes : déplacer celles qui doivent s'écarter
  // Les cartes entre qi et realInsert se décalent d'une hauteur de carte
  visibleCards.forEach((card, i) => {
    let shift = 0;
    if (realInsert <= qi) {
      // Déplacement vers le haut : cartes entre realInsert et qi-1 descendent
      if (i >= realInsert && i < qi) shift = cardH;
    } else {
      // Déplacement vers le bas : cartes entre qi+1 et realInsert montent
      if (i >= qi && i < realInsert) shift = -cardH;
    }
    card.style.transition = 'transform 0.18s cubic-bezier(.25,.8,.25,1)';
    card.style.transform  = shift ? `translateY(${shift}px)` : '';
  });
}

function finalizeDrag() {
  if (!dnd) return;
  const { qi, ghost, list, sourceCard, currentInsert } = dnd;

  // Restaurer scroll et styles
  list.style.touchAction = '';
  list.style.overflowY   = '';
  list.querySelectorAll('.q-card-mini').forEach(c => {
    c.style.transition    = '';
    c.style.transform     = '';
    c.style.opacity       = '';
    c.style.pointerEvents = '';
    c.style.touchAction   = '';
  });
  ghost.remove();
  dnd = null;

  // Appliquer le nouvel ordre
  const newIdx = Math.max(0, Math.min(currentInsert, questions.length - 1));
  if (newIdx !== qi) {
    const moved = questions.splice(qi, 1)[0];
    questions.splice(newIdx, 0, moved);
  }
  renderMiniCards();
}

function addQuestion() {
  questions.push({ question:'', answers:['','','',''], correct:0, time:20, image:'', explication:'' });
  renderQuestionList();
  $('questions-list').lastElementChild?.scrollIntoView({ behavior:'smooth' });
}
function removeQuestion(i) { questions.splice(i,1); renderQuestionList(); }
function setTime(i,val) { questions[i].time = parseInt(val); }

function escHtml(s) {
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

// ── Image handling ────────────────────────────────────────────────────────────
function pickImageFile(qi) { $(`img-file-${qi}`).click(); }

function handleImageFile(qi, e) {
  const file = e.target.files[0];
  if (!file) return;
  if (file.size > 800*1024) {
    if (!confirm(`Cette image fait ${(file.size/1024).toFixed(0)} Ko. Les grandes images peuvent ralentir le partage. Continuer ?`)) return;
  }
  // Resize before base64 to keep payload reasonable
  const img = new Image();
  const url = URL.createObjectURL(file);
  img.onload = () => {
    const MAX = 800;
    let w = img.width, h = img.height;
    if (w > MAX || h > MAX) {
      if (w > h) { h = Math.round(h * MAX / w); w = MAX; }
      else { w = Math.round(w * MAX / h); h = MAX; }
    }
    const canvas = document.createElement('canvas');
    canvas.width = w; canvas.height = h;
    canvas.getContext('2d').drawImage(img, 0, 0, w, h);
    questions[qi].image = canvas.toDataURL('image/jpeg', 0.82);
    URL.revokeObjectURL(url);
    renderQuestionList();
  };
  img.src = url;
  e.target.value = '';
}

async function pickImageUrl(qi) {
  const url = prompt("Colle l'URL de l'image :");
  if (!url) return;
  try {
    const resp = await fetch(url);
    if (!resp.ok) throw new Error('Impossible de charger l\'image');
    const blob = await resp.blob();
    if (!blob.type.startsWith('image/')) throw new Error('URL invalide (pas une image)');
    const reader = new FileReader();
    reader.onload = ev => { questions[qi].image = ev.target.result; renderQuestionList(); };
    reader.readAsDataURL(blob);
  } catch(err) {
    // CORS fallback: store URL directly
    questions[qi].image = url;
    renderQuestionList();
  }
}

function removeImage(qi) { questions[qi].image = ''; renderQuestionList(); }

// ── Import CSV/Excel ──────────────────────────────────────────────────────────
function triggerImport() { $('import-file').click(); }
function triggerImportPartie() { $('import-partie-file').click(); }

async function handleImport(e) {
  const file = e.target.files[0];
  if (!file) return;
  const ext = file.name.split('.').pop().toLowerCase();
  try {
    if (ext === 'csv') await importCSV(file);
    else if (ext === 'xlsx' || ext === 'xls') await importExcel(file);
    else alert('Format non supporté. Utilise .csv ou .xlsx');
  } catch(err) { alert('Erreur import : ' + err.message); }
  e.target.value = '';
}

async function importCSV(file) {
  const text = await file.text();
  const lines = text.split(/\r?\n/).filter(l => l.trim()).slice(1);
  const imported = lines.map(line => {
    const cols = parseCSVLine(line);
    if (cols.length < 6) return null;
    const [question,a1,a2,a3,a4,correctRaw,timeRaw,explication] = cols;
    if (!question.trim()) return null;
    const corrParsed = String(correctRaw||'1').split(',').map(s=>parseInt(s.trim())-1).filter(n=>n>=0&&n<=3);
    return { question:question.trim(), answers:[a1,a2,a3,a4].map(s=>s.trim()),
             correct: corrParsed.length===1 ? corrParsed[0] : corrParsed,
             time:parseInt(timeRaw)||20, image:'', explication:(explication||'').trim() };
  }).filter(Boolean);
  if (!imported.length) throw new Error('Aucune question valide trouvée.');
  questions = imported; renderQuestionList(); showImportSuccess(imported.length);
}

async function importExcel(file) {
  if (!window.XLSX) await loadScript('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js');
  const buf = await file.arrayBuffer();
  const wb = XLSX.read(buf, { type:'array' });
  const rows = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { header:1, defval:'' });
  const imported = rows.slice(1).map(row => {
    const [question,a1,a2,a3,a4,correctRaw,timeRaw,explication] = row;
    if (!String(question||'').trim()) return null;
    const corrRaw2 = String(correctRaw||'1').split(',').map(s=>parseInt(s.trim())-1).filter(n=>n>=0&&n<=3);
    return { question:String(question).trim(), answers:[a1,a2,a3,a4].map(s=>String(s||'').trim()),
             correct: corrRaw2.length===1 ? corrRaw2[0] : corrRaw2,
             time:parseInt(timeRaw)||20, image:'', explication:String(explication||'').trim() };
  }).filter(Boolean);
  if (!imported.length) throw new Error('Aucune question valide trouvée.');
  questions = imported; renderQuestionList(); showImportSuccess(imported.length);
}

async function handleImportPartie(e) {
  const file = e.target.files[0];
  if (!file) return;
  try {
    const text = await file.text();
    const data = JSON.parse(text);
    if (!data.questions || !Array.isArray(data.questions)) throw new Error('Format invalide');
    questions = data.questions.map(q => ({ explication:'', ...q }));
    renderQuestionList(); showImportSuccess(questions.length);
  } catch(err) { alert('Erreur import partie : ' + err.message); }
  e.target.value = '';
}

function parseCSVLine(line) {
  const cols = []; let cur = '', inQ = false;
  for (const c of line) {
    if (c === '"') inQ = !inQ;
    else if (c === ',' && !inQ) { cols.push(cur); cur = ''; }
    else cur += c;
  }
  cols.push(cur);
  return cols;
}

function loadScript(src) {
  return new Promise((res,rej) => {
    const s = document.createElement('script');
    s.src = src; s.onload = res; s.onerror = rej;
    document.head.appendChild(s);
  });
}

function showImportSuccess(count) {
  const msg = $('import-success');
  msg.textContent = `✅ ${count} question${count>1?'s':''} importée${count>1?'s':''}`;
  msg.style.display = 'block';
  setTimeout(() => { msg.style.display = 'none'; }, 3000);
}

function downloadTemplate() {
  const header = 'Question,Réponse1,Réponse2,Réponse3,Réponse4,BonneRéponse(1-4 séparés par virgule),Temps(s),Explication';
  const rows = [
    'Quelle est la capitale de la France ?,Madrid,Paris,Rome,Berlin,2,20,Paris est la capitale depuis des siècles.',
    'Combien de cordes a une guitare classique ?,4,5,6,7,3,15,',
    'Quel est le plus grand océan du monde ?,Atlantique,Indien,Arctique,Pacifique,4,20,Le Pacifique couvre 165 millions de km².',
  ];
  const blob = new Blob(['\uFEFF' + [header,...rows].join('\n')], { type:'text/csv;charset=utf-8' });
  dlBlob(blob, 'modele-questions.csv');
}

// ── Create Room ───────────────────────────────────────────────────────────────
async function createRoom() {
  const valid = questions.filter(q => {
    const hasQ = q.question.trim();
    const hasA = q.answers.every(a => a.trim());
    const correctArr = Array.isArray(q.correct) ? q.correct : [q.correct];
    const hasC = correctArr.length > 0;
    return hasQ && hasA && hasC;
  });
  if (!valid.length) {
    $('setup-error').textContent = 'Ajoute au moins une question complète';
    $('setup-error').style.display = 'block';
    return;
  }
  $('setup-error').style.display = 'none';
  currentQuestions = valid;

  // Strip images from JSON payload to avoid request size limit; send as separate field
  // Images are kept in currentQuestions for export but sent inline (base64 is fine for socket)
  try {
    const res = await fetch((_cfg.SERVER_URL||'') + '/api/room', {
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ questions: valid }),
    });
    // Guard against non-JSON response (e.g. Render cold-start HTML error page)
    const text = await res.text();
    let data;
    try { data = JSON.parse(text); }
    catch { throw new Error('Réponse serveur invalide. Le serveur est peut-être en cours de démarrage, réessaie dans 30 secondes.'); }
    if (data.error) throw new Error(data.error);
    roomCode = data.code;
    $('host-room-code').textContent = data.code;
    $('qr-img').src = data.qr;
    $('host-url').textContent = data.url;
    socket.emit('host:claim', { code: data.code });
    show('lobby');
  } catch(e) {
    $('setup-error').textContent = e.message;
    $('setup-error').style.display = 'block';
  }
}

// ── Replay ────────────────────────────────────────────────────────────────────
async function replayGame() {
  // Vider la liste des joueurs affichée avant de recréer la salle
  const lobbyPlayers = $('lobby-players');
  if (lobbyPlayers) lobbyPlayers.innerHTML = '';
  updatePlayerCount(0);
  const btn = $('btn-start');
  if (btn) { btn.disabled = true; btn.style.opacity = '.4'; }
  // Recréer avec les mêmes questions
  questions = currentQuestions.map(q => ({ ...q }));
  await createRoom();
}

// ── Socket events ─────────────────────────────────────────────────────────────
socket.on('host:claimed', ({ playerCount }) => updatePlayerCount(playerCount));

socket.on('host:playerJoined', ({ players }) => {
  updatePlayerCount(players.length);
  renderLobbyPlayers(players);
  $('btn-start').disabled = players.length < 1;
});
socket.on('host:playerLeft', ({ players }) => {
  updatePlayerCount(players.length);
  renderLobbyPlayers(players);
  $('btn-start').disabled = players.length < 1;
});
socket.on('host:answerUpdate', ({ answeredCount, totalPlayers }) => {
  $('stat-answered').textContent = answeredCount;
  $('stat-total').textContent = totalPlayers;
});

// ── Phase lecture (host voit la question sans les réponses) ──────────────────
socket.on('game:reading', ({ index, total, question, image, readTime }) => {
  $('host-q-counter').textContent = `Q ${index+1}/${total}`;
  $('host-q-text').textContent = question;
  $('stat-answered').textContent = '—';
  const imgEl = $('host-q-image');
  if (image) { imgEl.src = image; imgEl.style.display = 'block'; }
  else imgEl.style.display = 'none';
  $('host-answers').innerHTML = `<div style="color:var(--muted);font-size:.9rem;padding:16px;text-align:center">⏳ Les réponses apparaissent dans ${readTime}s…</div>`;
  // Show read countdown on host timer
  startHostTimer(readTime, true);
  show('question');
});

socket.on('game:question', ({ index, total, question, answers, timeLimit, image }) => {
  // Afficher le code salle dans les écrans de jeu
  const qrc = $('question-room-code');
  const rrc = $('results-room-code');
  if (qrc) qrc.textContent = roomCode;
  if (rrc) rrc.textContent = roomCode;
  $('host-q-counter').textContent = `Q ${index+1}/${total}`;
  $('host-q-text').textContent = question;
  $('stat-answered').textContent = '0';
  const imgEl = $('host-q-image');
  if (image) { imgEl.src = image; imgEl.style.display = 'block'; }
  else imgEl.style.display = 'none';
  const icons = ['▲','◆','●','■'];
  $('host-answers').innerHTML = answers.map((a,i) =>
    `<div class="host-answer a${i}"><span>${icons[i]}</span> ${escHtml(a)}</div>`
  ).join('');
  startHostTimer(timeLimit);
  show('question');
});

socket.on('game:questionEnd', ({ correctAnswers, correctAnswer, correctLabel, leaderboard, isLast }) => {
  clearInterval(timerInterval);
  const corrArr = correctAnswers || (correctAnswer !== undefined ? [correctAnswer] : []);
  document.querySelectorAll('.host-answer').forEach((el,i) => {
    if (corrArr.includes(i)) el.classList.add('correct-host');
    else el.style.opacity = '.4';
  });
  setTimeout(() => {
    $('host-correct-label').textContent = `✅ Bonne réponse : ${correctLabel}`;
    renderLeaderboard('host-lb-mid', leaderboard);
    // Adapter le libellé du bouton
    const btnNext = $('btn-next-q');
    if (btnNext) {
      btnNext.textContent = isLast ? 'Voir le podium final 🏆' : 'Question suivante ▶';
      btnNext.className = isLast ? 'btn btn-success mt-24' : 'btn btn-primary mt-24';
      btnNext.style.maxWidth = '320px';
    }
    show('results');
  }, 1500);
});

socket.on('game:over', ({ leaderboard }) => {
  clearInterval(timerInterval);
  finalLeaderboard = leaderboard;
  renderLeaderboard('host-lb-final', leaderboard);
  show('over');
});

socket.on('error', msg => alert(msg));

function copyUrl() {
  const url = $('host-url')?.textContent;
  if (!url) return;
  navigator.clipboard.writeText(url).then(() => {
    const btn = $('btn-copy-url');
    if (btn) { btn.textContent = '✅ Copié !'; setTimeout(() => btn.textContent = '📋 Copier l\'URL', 2000); }
  }).catch(() => {
    // Fallback
    const ta = document.createElement('textarea');
    ta.value = url; document.body.appendChild(ta); ta.select();
    document.execCommand('copy'); document.body.removeChild(ta);
    const btn = $('btn-copy-url');
    if (btn) { btn.textContent = '✅ Copié !'; setTimeout(() => btn.textContent = '📋 Copier l\'URL', 2000); }
  });
}

function startGame()    { socket.emit('host:start', { code: roomCode }); }
function nextQuestion() { socket.emit('host:next',  { code: roomCode }); }

// ── Timer (affiché -1s pour laisser le temps au réseau) ──────────────────────
function startHostTimer(seconds, isReading = false) {
  clearInterval(timerInterval);
  const displayed = isReading ? seconds : seconds - 1;
  let remaining = displayed;
  const circle = $('host-timer-circle'), num = $('host-timer-num'), prog = $('host-q-progress');
  function tick() {
    const safe = Math.max(0, remaining);
    num.textContent = safe;
    circle.style.strokeDashoffset = CIRCUMFERENCE * (1 - safe / displayed);
    prog.style.width = (safe / displayed * 100) + '%';
    if (isReading) {
      circle.style.stroke = 'var(--accent)';
    } else {
      const pct = safe / displayed;
      circle.style.stroke = pct > .5 ? 'var(--green)' : pct > .25 ? 'var(--yellow)' : 'var(--red)';
    }
    if (remaining <= 0) clearInterval(timerInterval);
    remaining--;
  }
  tick();
  timerInterval = setInterval(tick, 1000);
}

// ── Exports ───────────────────────────────────────────────────────────────────
async function exportResultats() {
  if (!window.XLSX) await loadScript('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js');

  // Fetch detailed results from server
  let detailedPlayers = null;
  try {
    const res = await fetch((_cfg.SERVER_URL||'') + '/api/room/' + roomCode + '/results');
    const data = await res.json();
    detailedPlayers = data.players;
  } catch(e) {
    console.warn('Could not fetch detailed results, using leaderboard only', e);
  }

  const wb = XLSX.utils.book_new();

  // ── Feuille 1 : Classement général ──────────────────────────────────────────
  const lbData = [
    ['Rang','Joueur','Score total'],
    ...finalLeaderboard.map((p,i) => [i+1, p.name, p.score])
  ];
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(lbData), 'Classement');

  // ── Feuille 2 : Détail par joueur ────────────────────────────────────────────
  if (detailedPlayers) {
    const detailHeader = [
      'Joueur', 'Rang', 'Score total',
      'N° question', 'Question', 'Réponse donnée', 'Bonne réponse',
      'Correct ?', 'Temps (s)', 'Points base', 'Bonus vitesse', 'Points question'
    ];
    const detailRows = [];
    for (const p of detailedPlayers) {
      if (!p.history || !p.history.length) {
        detailRows.push([p.name, p.rank, p.score, '—','—','—','—','—','—','—','—','—']);
        continue;
      }
      for (const h of p.history) {
        detailRows.push([
          p.name, p.rank, p.score,
          h.questionIndex + 1,
          h.question,
          h.given,
          h.correct,
          h.isCorrect ? 'Oui ✓' : 'Non ✗',
          h.elapsed,
          h.basePoints,
          h.speedBonus,
          h.points,
        ]);
      }
    }
    const detailSheet = XLSX.utils.aoa_to_sheet([detailHeader, ...detailRows]);
    // Column widths
    detailSheet['!cols'] = [14,6,10,8,40,20,20,8,8,10,10,10].map(w=>({wch:w}));
    XLSX.utils.book_append_sheet(wb, detailSheet, 'Détail par joueur');
  }

  // ── Feuille 3 : Questions ────────────────────────────────────────────────────
  const qData = [
    ['N°','Question','Réponse 1','Réponse 2','Réponse 3','Réponse 4','Bonne réponse','Temps (s)','Explication'],
    ...currentQuestions.map((q,i) => {
      const corrArr = Array.isArray(q.correct) ? q.correct : [q.correct];
      const corrLabel = corrArr.map(ci => q.answers[ci]).join(' / ');
      return [i+1, q.question, ...q.answers, corrLabel, q.time, q.explication||''];
    })
  ];
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(qData), 'Questions');

  const buf = XLSX.write(wb, { type:'array', bookType:'xlsx' });
  dlBlob(new Blob([buf],{type:'application/octet-stream'}),
    `resultats-quiz-${new Date().toISOString().slice(0,10)}.xlsx`);
}

// Export avant création de salle (depuis écran setup)
function exportPartieAvantJeu() {
  const valid = questions.filter(q => {
    const hasQ = q.question.trim();
    const hasA = q.answers.every(a => a.trim());
    const correctArr = Array.isArray(q.correct) ? q.correct : [q.correct];
    const hasC = correctArr.length > 0;
    return hasQ && hasA && hasC;
  });
  if (!valid.length) { alert('Aucune question complète à exporter.'); return; }
  const data = {
    titre: `Partie exportée le ${new Date().toLocaleDateString('fr-FR')}`,
    exportDate: new Date().toISOString(),
    questions: valid,
  };
  dlBlob(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),
    `partie-quiz-${new Date().toISOString().slice(0,10)}.json`);
}

function exportPartie() {
  const data = { titre:`Partie du ${new Date().toLocaleDateString('fr-FR')}`, exportDate:new Date().toISOString(), questions:currentQuestions };
  dlBlob(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}), `partie-quiz-${new Date().toISOString().slice(0,10)}.json`);
}

function dlBlob(blob, filename) {
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob); a.download = filename; a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
}

// ── UI helpers ────────────────────────────────────────────────────────────────
function updatePlayerCount(n) {
  $('host-player-count').innerHTML = `<span class="dot"></span> ${n} joueur${n>1?'s':''} connecté${n>1?'s':''}`;
  const btn = $('btn-start');
  if (btn) { btn.disabled = n < 1; btn.style.opacity = n < 1 ? '.4' : '1'; }
}
function renderLobbyPlayers(players) {
  $('lobby-players').innerHTML = players.map(p => {
    const av = window.generateAvatar ? window.generateAvatar(p.name) : '🎮';
    return `<div class="lb-row">
      <span class="av-circle">${av}</span>
      <span class="lb-name">${escHtml(p.name)}</span>
    </div>`;
  }).join('');
}
const medals = ['🥇','🥈','🥉'];
function renderLeaderboard(containerId, lb) {
  $(containerId).innerHTML = lb.map((p,i) => {
    const av = window.generateAvatar ? window.generateAvatar(p.name) : '';
    return `
      <div class="lb-row" style="animation-delay:${i*.06}s">
        <span class="lb-rank">${medals[i]||`${i+1}`}</span>
        <span class="av-circle">${av}</span>
        <span class="lb-name">${escHtml(p.name)}</span>
        <span class="lb-score">${p.score.toLocaleString()}</span>
      </div>`;
  }).join('');
}
